'use client';
import Image from 'next/image';import Link from 'next/link';import {Product} from '@/types';import {formatPrice} from '@/lib/config';import {useCart} from './store';
export function ProductCard({product}:{product:Product}){const{add}=useCart();return <article className="group"><Link href={`/product/${product.slug}`} className="relative block bg-sand overflow-hidden aspect-[4/5]"><Image src={product.images[0]} alt={product.name} fill className="object-cover transition duration-700 group-hover:scale-[1.035]"/>{(product.isNew||product.isSale)&&<span className="absolute top-3 left-3 bg-white px-3 py-1 text-[9px] tracking-widest">{product.isSale?'SALE':'NEW'}</span>}</Link><div className="pt-4"><Link href={`/product/${product.slug}`}><h3 className="text-sm">{product.name}</h3></Link><div className="flex justify-between items-end mt-2"><p className="text-sm"><b>{formatPrice(product.price)}</b>{product.oldPrice&&<s className="text-muted ml-2">{formatPrice(product.oldPrice)}</s>}</p><button onClick={()=>add(product,product.colors[0],product.sizes[2])} className="text-[10px] uppercase tracking-wider border-b border-black">Быстро добавить</button></div><div className="flex gap-2 mt-3">{product.colors.map(c=><i title={c} key={c} className="w-3 h-3 rounded-full border border-black/20" style={{background:c==='Black'?'#222':c==='White'?'#fff':'#c8ad82'}}/>)}</div></div></article>}
export function ProductGrid({products}:{products:Product[]}){return <div className="grid grid-cols-2 lg:grid-cols-4 gap-x-4 gap-y-10 md:gap-x-7">{products.map(p=><ProductCard key={p.id} product={p}/>)}</div>}
